prop w_shutter 15 1
prop w_shutter2 18 1
text 18 2 "'혼수 이불'. 셔터 아래로 솜이 삐져나왔다. 쥐가 아니라 사람이 꺼내 간 자리." w=2
prop w_shop_parts 21 1
prop w_shutter3 24 1
text 24 2 "'광명 안경'. 반쯤 올린 셔터 안 진열대에 안경테만 수십 개. 렌즈는 하나도 없다." w=2
prop w_shutter 27 1
prop w_shop_meds 30 1
prop w_shutter2 33 1
prop w_shutter3 36 1
prop w_shutter_big 41 1
text 41 2 "3구역 셔터. 용접 자국과 쇠사슬 세 겹. 분필 — '대피민 휴면 — 열지 말 것. 번영회'." w=3
# 탁만수 구두 수선 좌판(JH-02)
prop gt_shoe_stall 20 12
npc N-UG-501 21 11 S cond="FQ_JH02_TAK == 0 or FQ_JH02_TAK == 1" bark="굽 갈아 줄까? 밑창은 사람 따라 닳아."
text 20 12 "구두 수선 좌판. 구두골 옆에 낡은 코트가 걸려 있었던 못 자국 — 주인이 입고 나갔다." w=2 cond="FQ_JH02_TAK >= 2 and dead(\"N-UG-501\") == 0"
text 20 12 "구두 수선 좌판. 망치와 구두골이 그대로다. 공동체 누군가 흰 국화 한 송이를 올려 두었다." w=2 cond="dead(\"N-UG-501\") == 1"
# 무진 잡화(낮엔 세이프빌 왕복)
prop stall_parts 30 12
npc N-UG-040 31 11 S cond="GAME_HOUR >= 17 or GAME_HOUR < 8" bark="세이프빌 사람들은 값은 안 깎아. 대신 사람을 깎지."
text 30 12 "잡화 좌판. 분필 — '무진 — 세이프빌 다녀옴. 해 지면.'" w=2 cond="GAME_HOUR >= 8 and GAME_HOUR < 17"
